package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import java.util.*;
/** Actual Home geometry: one action row, no fixed FM stage, all presets visible. */
public class PanelLayoutChecks extends Instrumentation {
 LauncherActivity a;int n;android.content.SharedPreferences prefs;Map<String,?> before;
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);n++;}
 void ui(Runnable r){Throwable[] e={null};runOnMainSync(()->{try{r.run();}catch(Throwable t){e[0]=t;}});waitForIdleSync();if(e[0]!=null)throw new AssertionError(e[0]);}
 View find(View v,String desc){if(desc.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View x=find(((ViewGroup)v).getChildAt(i),desc);if(x!=null)return x;}return null;}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_CANCELED;try{
 prefs=getTargetContext().getSharedPreferences("idash",0);before=new HashMap<>(prefs.getAll());prefs.edit().putInt("panel_mode",1).putBoolean("fm_premium",true).apply();a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ui(()->{a.page="home";a.panelVisible=true;a.render();
 for(int res:new int[]{0,1,4})for(int[] size:new int[][]{{1024,600},{800,480}}){prefs.edit().putInt(ResolutionStage.PREF,res).apply();a.rebuildPanel();a.stage.measure(View.MeasureSpec.makeMeasureSpec(size[0],View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(size[1],View.MeasureSpec.EXACTLY));a.stage.layout(0,0,size[0],size[1]);
 View mode=find(a.stage,"Panel Mode"),layout=find(a.stage,"Panel Layout"),close=find(a.stage,"Panel Close"),panel=find(a.stage,"Panel"),custom=find(a.stage,"Customize");check(mode.getParent()==panel.getParent()&&mode.getParent()==custom.getParent()&&mode.getParent()==close.getParent()&&mode.getParent()==layout.getParent(),"all controls in top row");ViewGroup row=(ViewGroup)mode.getParent();int right=0;for(int i=0;i<row.getChildCount();i++){View v=row.getChildAt(i);check(v.getLeft()>=right&&v.getRight()<=row.getWidth(),"top actions stay inside display");right=v.getRight();}
 check(a.shell.getPaddingRight()==4,"compact safe right edge");check(a.panelBox.getRight()==((ViewGroup)a.panelBox.getParent()).getWidth(),"panel uses all available row width");
 check(a.panelBox.getChildCount()==1&&a.fmPanel.getParent()==a.panelBox,"no panel title or fixed FM stage");check(a.fmPanel.getWidth()==a.panelBox.getWidth()-a.panelBox.getPaddingLeft()-a.panelBox.getPaddingRight()&&a.fmPanel.getHeight()==a.panelBox.getHeight()-a.panelBox.getPaddingTop()-a.panelBox.getPaddingBottom(),"FM fills panel for every web preset");check(a.fmPanel.getScaleX()==1f&&a.fmPanel.getTranslationX()==0f,"FM not letterboxed or transformed");View preset=find(a.fmPanel,"FM channel 10; empty; hold to save");if(preset==null){ViewGroup fm=(ViewGroup)a.fmPanel.getChildAt(0);ViewGroup last=(ViewGroup)fm.getChildAt(fm.getChildCount()-1);preset=last.getChildAt(4);}int[] at=new int[2],bounds=new int[2];preset.getLocationOnScreen(at);a.fmPanel.getLocationOnScreen(bounds);check(at[1]+preset.getHeight()<=bounds[1]+a.fmPanel.getHeight()&&preset.getHeight()>=48,"last preset visible and tappable");}
 a.render();});
 ui(()->{ContentInsets fit=new ContentInsets(a,a.stage,a.shell,20,8,4,8);fit.read(a.stage.getRootWindowInsets().replaceSystemWindowInsets(0,0,48,0));fit.apply();check(a.shell.getPaddingRight()==4,"hidden navigation stale inset leaves no blank strip");});
 ui(()->{a.page="drive";a.render();a.driveDashboard.setMode(2);});
 ui(()->{DriveDashboard d=a.driveDashboard;check(a.shell.getPaddingRight()==4,"Drive safe edge");check(d.getChildAt(2).getRight()==d.getWidth(),"Drive main area reaches available right edge");check(d.fm.getWidth()==d.mapHost.getWidth(),"radio reaches main area's right edge");a.page="home";a.panelVisible=true;a.render();});android.graphics.Bitmap shot=getUiAutomation().takeScreenshot();if(shot!=null){try(java.io.OutputStream f=new java.io.FileOutputStream(new java.io.File(a.getFilesDir(),"panel-layout.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}shot.recycle();}out.putString("stream","PASS: "+n+" panel layout assertions\n");code=Activity.RESULT_OK;
 }catch(Throwable t){out.putString("stream","FAIL after "+n+": "+t+"\n");}finally{if(a!=null)ui(a::finish);if(prefs!=null&&before!=null)AppearanceChecks.restore(prefs,before);}finish(code,out);}
}
